DATA_CONTRACT_MUTATION_PROSRC = r"""
        BEGIN
          RAISE EXCEPTION 'historical data contracts are append-only';
          RETURN NULL;
        END"""
DATA_CONTRACT_TRUNCATE_PROSRC = r"""
        BEGIN
          IF current_database() LIKE 'test_%' ESCAPE '|'
             AND EXISTS(
               SELECT 1 FROM pg_locks locks
               WHERE locks.pid=pg_backend_pid() AND locks.granted
                 AND locks.mode='AccessExclusiveLock'
                 AND locks.relation='auth_permission'::regclass
             ) THEN RETURN NULL; END IF;
          RAISE EXCEPTION 'historical data contracts reject truncation';
          RETURN NULL;
        END"""
REPLACEMENT_PLAN_PROSRC = r"""
        DECLARE contract record; strategy record; discovery record; mismatched integer;
                request_count integer; discovery_chunks integer; total_expected bigint;
                inventory_total bigint;
        BEGIN
          SELECT * INTO STRICT contract FROM market_historicaldatacontract
            WHERE id=plan.data_contract_id;
          SELECT r.plan_id AS discovery_plan_id, p.sha256 AS discovery_plan_sha,
                 p.sealed_at
            INTO STRICT discovery
            FROM market_historicaldiscoveryregistration r
            JOIN market_historicaldiscoveryplan p ON p.id=r.plan_id
            WHERE r.id=contract.discovery_registration_id;
          SELECT v.* INTO STRICT strategy FROM research_strategyversion v
            WHERE v.id=plan.strategy_version_id;
          IF plan.identity<>contract.identity
             OR plan.data_contract_sha256<>contract.sha256
             OR contract.strategy_version_id<>plan.strategy_version_id
             OR discovery.sealed_at IS NULL
             OR discovery.discovery_plan_sha<>'2a25bbc28fca5d596b26d3d2921fa881e374174fb08cc1dbfb51e47c8b138e3a'
             OR plan.phase1_spec_hash<>contract.phase1_spec_hash
             OR plan.phase1_manifest_hash<>contract.phase1_manifest_hash
             OR strategy.content_hash<>contract.phase1_manifest_hash
             OR strategy.data_identity<>contract.superseded_data_identity
             OR plan.instruments<>'["AUD_USD","EUR_GBP","EUR_USD","GBP_USD","USD_CAD","USD_JPY"]'::jsonb
             OR plan.granularities<>'["D","H1","W"]'::jsonb
             OR plan.alignment<>'{"timezone":"America/New_York","daily_hour":17,"weekly_day":"Friday","smooth":false}'::jsonb
             OR plan.price_component<>'COMBINED_BID_ASK' OR NOT plan.complete_only
             OR plan.payload->>'acquisition_contract'<>'failed-break-provider-observed-historical-acquisition'
             OR plan.payload->>'acquisition_version'<>'phase-2b1r-v1'
             OR plan.payload->>'data_identity'<>contract.identity
             OR plan.payload->>'data_contract_sha256'<>contract.sha256
             OR plan.payload->>'discovery_plan_sha256'<>discovery.discovery_plan_sha
             OR plan.payload->'strategy'->>'content_hash'<>strategy.content_hash
             OR plan.payload->>'phase1_spec_hash'<>plan.phase1_spec_hash
             OR plan.payload->>'phase1_manifest_hash'<>plan.phase1_manifest_hash
             OR plan.sha256<>market_sha256(plan.payload)
          THEN RAISE EXCEPTION
            'replacement plan conflicts with the data contract'; END IF;
          SELECT count(*) INTO discovery_chunks FROM market_historicaldiscoverychunk c
            WHERE c.plan_id=discovery.discovery_plan_id;
          SELECT count(*), coalesce(sum((request->>'expected_observation_count')::integer),0)
            INTO request_count, total_expected
            FROM jsonb_array_elements(plan.payload->'requests') AS request;
          SELECT count(*) INTO mismatched
            FROM jsonb_array_elements(plan.payload->'requests') AS request
            LEFT JOIN market_historicaldiscoverychunk c
              ON c.plan_id=discovery.discovery_plan_id
             AND c.ordinal=(request->>'ordinal')::integer
            LEFT JOIN market_historicaltimestampinventory i ON i.chunk_id=c.id
            LEFT JOIN market_instrument ins ON ins.id=c.instrument_id
            WHERE c.id IS NULL OR i.id IS NULL
               OR request->'canonical_request' IS DISTINCT FROM c.canonical_request
               OR request->>'canonical_request_sha256'
                  IS DISTINCT FROM c.canonical_request_sha256
               OR request->>'semantic_inventory_sha256'
                  IS DISTINCT FROM i.semantic_inventory_sha256
               OR (request->>'expected_observation_count')::integer
                  IS DISTINCT FROM i.observation_count
               OR request->>'instrument' IS DISTINCT FROM ins.code
               OR request->>'granularity' IS DISTINCT FROM c.granularity;
          SELECT coalesce(sum(i.observation_count),0) INTO inventory_total
            FROM market_historicaltimestampinventory i
            JOIN market_historicaldiscoverychunk c ON c.id=i.chunk_id
            WHERE c.plan_id=discovery.discovery_plan_id;
          IF request_count<>discovery_chunks OR mismatched<>0
             OR total_expected<>inventory_total
             OR (plan.payload->>'expected_total_observations')::bigint<>inventory_total
          THEN RAISE EXCEPTION
            'replacement plan does not reconstruct the sealed inventory'; END IF;
        END"""
REPLACEMENT_CHUNK_PROSRC = r"""
        DECLARE plan record; contract record; dataset record; lineage record;
                expected_key text;
        BEGIN
          SELECT * INTO STRICT plan FROM market_historicaldatasetplan WHERE id=chunk.plan_id;
          SELECT * INTO STRICT contract FROM market_historicaldatacontract
            WHERE id=plan.data_contract_id;
          SELECT * INTO STRICT dataset FROM market_datasetversion
            WHERE id=chunk.dataset_version_id;
          IF chunk.discovery_inventory_id IS NULL OR chunk.semantic_inventory_sha256 IS NULL
             OR chunk.expected_observation_count IS NULL OR chunk.data_contract_sha256 IS NULL
          THEN RAISE EXCEPTION 'replacement chunk requires sealed inventory lineage'; END IF;
          SELECT i.semantic_inventory_sha256, i.observation_count,
                 c.canonical_request AS discovery_request,
                 c.canonical_request_sha256 AS discovery_request_sha,
                 c.instrument_id AS discovery_instrument,
                 c.granularity AS discovery_granularity,
                 c.requested_from AS discovery_from, c.requested_to AS discovery_to,
                 c.plan_id AS discovery_plan_id, r.plan_id AS registration_plan_id
            INTO STRICT lineage
            FROM market_historicaltimestampinventory i
            JOIN market_historicaldiscoverychunk c ON c.id=i.chunk_id
            JOIN market_historicaldiscoveryregistration r
              ON r.id=contract.discovery_registration_id
            WHERE i.id=chunk.discovery_inventory_id;
          expected_key := market_sha256(jsonb_build_object(
            'canonical_request_sha256',chunk.canonical_request_sha256,
            'replacement_dataset_manifest_sha256',dataset.manifest_sha256,
            'replacement_plan_sha256',plan.sha256,
            'semantic_inventory_sha256',chunk.semantic_inventory_sha256));
          IF chunk.data_contract_sha256<>contract.sha256
             OR lineage.semantic_inventory_sha256<>chunk.semantic_inventory_sha256
             OR lineage.observation_count<>chunk.expected_observation_count
             OR chunk.expected_observation_count NOT BETWEEN 1 AND 4999
             OR lineage.discovery_plan_id<>lineage.registration_plan_id
             OR lineage.discovery_request IS DISTINCT FROM chunk.canonical_request
             OR lineage.discovery_request_sha<>chunk.canonical_request_sha256
             OR lineage.discovery_instrument<>chunk.instrument_id
             OR lineage.discovery_granularity<>chunk.granularity
             OR lineage.discovery_from<>chunk.requested_from
             OR lineage.discovery_to<>chunk.requested_to
             OR chunk.logical_key<>expected_key
             OR dataset.manifest->>'historical_plan_sha256' IS DISTINCT FROM plan.sha256
             OR dataset.data_contract_sha256 IS DISTINCT FROM contract.sha256
             OR EXISTS (SELECT 1 FROM market_datasetregistration
                        WHERE dataset_version_id=chunk.dataset_version_id)
          THEN RAISE EXCEPTION
            'replacement chunk conflicts with sealed inventory lineage'; END IF;
        END"""
REPLACEMENT_DATASET_PROSRC = r"""
        DECLARE plan record; contract record; strategy record; expected_manifest jsonb;
                required_ranges jsonb;
        BEGIN
          SELECT * INTO STRICT plan FROM market_historicaldatasetplan
            WHERE sha256=dataset.manifest->>'historical_plan_sha256';
          SELECT * INTO STRICT contract FROM market_historicaldatacontract
            WHERE id=plan.data_contract_id;
          SELECT * INTO STRICT strategy FROM research_strategyversion
            WHERE id=plan.strategy_version_id;
          SELECT jsonb_agg(jsonb_build_object(
                   'instrument',instrument.value,
                   'granularity',granularity.value,
                   'start',plan.ranges->granularity.value->'from',
                   'end',plan.ranges->granularity.value->'to')
                   ORDER BY instrument.ordinality,granularity.ordinality)
            INTO required_ranges
            FROM jsonb_array_elements_text(plan.instruments)
                   WITH ORDINALITY AS instrument(value,ordinality)
            CROSS JOIN jsonb_array_elements_text(plan.granularities)
                   WITH ORDINALITY AS granularity(value,ordinality);
          expected_manifest := jsonb_build_object(
            'strategy_manifest_sha256',strategy.content_hash,
            'partition',jsonb_build_object(
              'name','development','start_year',2010,'end_year',2018),
            'required_ranges',required_ranges,
            'historical_plan_sha256',plan.sha256,
            'price_component',plan.price_component,
            'complete_only',plan.complete_only,
            'instruments',plan.instruments,
            'granularities',plan.granularities,
            'alignment',plan.alignment,
            'data_identity',contract.identity,
            'historical_data_contract_sha256',contract.sha256,
            'global_semantic_inventory_sha256',contract.global_semantic_inventory_sha256);
          IF dataset.source_id<>plan.source_id
             OR dataset.name<>plan.payload->'dataset'->>'name'
             OR dataset.version<>plan.payload->'dataset'->>'version'
             OR dataset.description<>plan.payload->'dataset'->>'description'
             OR dataset.manifest<>expected_manifest
             OR dataset.manifest_sha256<>market_sha256(expected_manifest)
             OR dataset.data_contract_sha256 IS DISTINCT FROM contract.sha256
          THEN RAISE EXCEPTION
            'replacement dataset conflicts with contract lineage'; END IF;
        END"""
REPLACEMENT_REGISTRATION_PROSRC = r"""
        DECLARE plan record; dataset record; contract record; expected_logical text;
                expected_attempt text; expected_manifest_hash text; expected_series jsonb;
                expected_candle_keys text; expected_candle_payloads text;
                configuration jsonb; report jsonb; bad_chunks integer; bad_series integer;
                total_expected bigint; total_candles bigint;
        BEGIN
          LOCK TABLE market_historicalingestionchunk, market_historicalingestionattempt,
            market_ingestionrun, market_ingestionmanifest, market_candle
            IN SHARE ROW EXCLUSIVE MODE;
          SELECT * INTO STRICT plan FROM market_historicaldatasetplan WHERE id=reg.plan_id;
          SELECT * INTO STRICT dataset FROM market_datasetversion
            WHERE id=reg.dataset_version_id;
          SELECT * INTO STRICT contract FROM market_historicaldatacontract
            WHERE id=plan.data_contract_id;
          SELECT market_sha256(coalesce(jsonb_agg(c.logical_key
                   ORDER BY i.code,c.granularity,c.requested_from),'[]'))
            INTO expected_logical FROM market_historicalingestionchunk c
            JOIN market_instrument i ON i.id=c.instrument_id
            WHERE c.plan_id=reg.plan_id AND c.dataset_version_id=reg.dataset_version_id;
          SELECT market_sha256(coalesce(jsonb_agg(a.idempotency_key
                   ORDER BY i.code,c.granularity,c.requested_from),'[]')),
                 market_sha256(coalesce(jsonb_agg(m.sha256 ORDER BY m.sha256),'[]'))
            INTO expected_attempt, expected_manifest_hash
            FROM market_historicalingestionchunk c
            JOIN market_historicalingestionattempt a ON a.chunk_id=c.id
            JOIN market_ingestionrun r ON r.id=a.ingestion_run_id AND r.status='succeeded'
            JOIN market_ingestionmanifest m ON m.ingestion_run_id=r.id
            JOIN market_instrument i ON i.id=c.instrument_id
            WHERE c.plan_id=reg.plan_id AND c.dataset_version_id=reg.dataset_version_id;
          SELECT jsonb_agg(jsonb_build_object('series',instrument||':'||granularity,
                   'range',plan.ranges->granularity,
                   'row_count',(SELECT coalesce(sum(c.expected_observation_count),0)
                     FROM market_historicalingestionchunk c
                     JOIN market_instrument i ON i.id=c.instrument_id
                     WHERE c.plan_id=reg.plan_id
                       AND c.dataset_version_id=reg.dataset_version_id
                       AND i.code=instrument AND c.granularity=granularity))
                   ORDER BY instrument_order,granularity_order)
            INTO expected_series
            FROM jsonb_array_elements_text(plan.instruments)
              WITH ORDINALITY instruments(instrument,instrument_order)
            CROSS JOIN jsonb_array_elements_text(plan.granularities)
              WITH ORDINALITY granularities(granularity,granularity_order);
          SELECT encode(digest(convert_to(coalesce(string_agg(market_canonical_json(jsonb_build_array(
                    i.code,c.granularity,to_char(c.timestamp AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||'+00:00')),
                    '' ORDER BY i.code,c.granularity,c.timestamp),''),'UTF8'),'sha256'),'hex'),
                 encode(digest(convert_to(coalesce(string_agg(market_canonical_json(jsonb_build_array(
                    i.code,c.granularity,to_char(c.timestamp AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||'+00:00',
                    c.complete,c.volume,to_char(c.bid_open,'FM999999999990.000000'),
                    to_char(c.bid_high,'FM999999999990.000000'),to_char(c.bid_low,'FM999999999990.000000'),
                    to_char(c.bid_close,'FM999999999990.000000'),to_char(c.ask_open,'FM999999999990.000000'),
                    to_char(c.ask_high,'FM999999999990.000000'),to_char(c.ask_low,'FM999999999990.000000'),
                    to_char(c.ask_close,'FM999999999990.000000'))),
                    '' ORDER BY i.code,c.granularity,c.timestamp),''),'UTF8'),'sha256'),'hex')
            INTO expected_candle_keys,expected_candle_payloads FROM market_candle c
            JOIN market_instrument i ON i.id=c.instrument_id
            WHERE c.dataset_version_id=reg.dataset_version_id;
          configuration := jsonb_build_object(
            'identity','failed-break-provider-observed-dataset-registration-v1',
            'plan_sha256',plan.sha256,'dataset_manifest_sha256',dataset.manifest_sha256,
            'price_component','COMBINED_BID_ASK',
            'logical_chunk_set_hash',reg.logical_chunk_set_hash,
            'data_contract_sha256',contract.sha256,
            'global_semantic_inventory_sha256',reg.global_semantic_inventory_sha256);
          report := jsonb_build_object('configuration_sha256',reg.configuration_sha256,
            'series_manifest',reg.series_manifest,'row_counts',reg.row_counts,
            'first_last_timestamps',reg.first_last_timestamps,'missingness',reg.missingness,
            'conflict_count',reg.conflict_count,'incident_count',reg.incident_count,
            'logical_chunk_set_hash',reg.logical_chunk_set_hash,
            'successful_attempt_set_hash',reg.successful_attempt_set_hash,
            'ingestion_manifest_set_hash',reg.ingestion_manifest_set_hash,
            'candle_key_hash',reg.candle_key_hash,'candle_payload_hash',reg.candle_payload_hash);
          SELECT coalesce(sum(c.expected_observation_count),0) INTO total_expected
            FROM market_historicalingestionchunk c
            WHERE c.plan_id=reg.plan_id AND c.dataset_version_id=reg.dataset_version_id;
          SELECT count(*) INTO total_candles FROM market_candle
            WHERE dataset_version_id=reg.dataset_version_id;
          IF reg.data_contract_id IS DISTINCT FROM plan.data_contract_id
             OR reg.global_semantic_inventory_sha256
                IS DISTINCT FROM contract.global_semantic_inventory_sha256
             OR dataset.data_contract_sha256 IS DISTINCT FROM contract.sha256
             OR dataset.manifest_sha256<>market_sha256(dataset.manifest)
             OR dataset.manifest->>'historical_plan_sha256' IS DISTINCT FROM plan.sha256
             OR dataset.manifest->>'historical_data_contract_sha256'
                IS DISTINCT FROM contract.sha256
             OR dataset.manifest->>'global_semantic_inventory_sha256'
                IS DISTINCT FROM contract.global_semantic_inventory_sha256
             OR reg.logical_chunk_set_hash<>expected_logical
             OR reg.successful_attempt_set_hash<>expected_attempt
             OR reg.ingestion_manifest_set_hash<>expected_manifest_hash
             OR reg.series_manifest<>expected_series
             OR reg.candle_key_hash<>expected_candle_keys
             OR reg.candle_payload_hash<>expected_candle_payloads
             OR reg.configuration_sha256<>market_sha256(configuration)
             OR reg.report_sha256<>market_sha256(report)
             OR reg.conflict_count<>0 OR reg.incident_count<>0
             OR (SELECT count(*) FROM jsonb_object_keys(reg.row_counts))<>18
             OR (SELECT count(*) FROM jsonb_object_keys(reg.first_last_timestamps))<>18
             OR (SELECT count(*) FROM jsonb_object_keys(reg.missingness))<>18
             OR total_candles<>total_expected
             OR EXISTS (SELECT 1 FROM market_ingestionrun r
                  WHERE r.dataset_version_id=reg.dataset_version_id
                    AND (r.status='running' OR NOT EXISTS
                      (SELECT 1 FROM market_historicalingestionattempt a
                       WHERE a.ingestion_run_id=r.id)))
             OR EXISTS (SELECT 1 FROM market_historicalingestionchunk c
                  WHERE c.plan_id=reg.plan_id
                    AND c.dataset_version_id=reg.dataset_version_id AND
                  (SELECT count(*) FROM market_historicalingestionattempt a
                   JOIN market_ingestionrun r ON r.id=a.ingestion_run_id
                   JOIN market_ingestionmanifest m ON m.ingestion_run_id=r.id
                   WHERE a.chunk_id=c.id AND r.status='succeeded')<>1)
             OR EXISTS (SELECT 1 FROM market_candleconflict
                  WHERE dataset_version_id=reg.dataset_version_id)
             OR EXISTS (SELECT 1 FROM market_dataqualityincident
                  WHERE dataset_version_id=reg.dataset_version_id)
             OR EXISTS (SELECT 1 FROM market_candle c
                  JOIN market_ingestionrun r ON r.id=c.ingestion_run_id
                  LEFT JOIN market_ingestionmanifest m ON m.ingestion_run_id=r.id
                  LEFT JOIN market_historicalingestionattempt a ON a.ingestion_run_id=r.id
                  LEFT JOIN market_historicalingestionchunk h ON h.id=a.chunk_id
                  WHERE c.dataset_version_id=reg.dataset_version_id AND (r.status<>'succeeded'
                    OR r.dataset_version_id<>reg.dataset_version_id
                    OR m.dataset_version_id<>reg.dataset_version_id
                    OR h.dataset_version_id<>reg.dataset_version_id
                    OR h.instrument_id<>c.instrument_id
                    OR h.granularity<>c.granularity OR c.timestamp<h.requested_from
                    OR c.timestamp>=h.requested_to))
          THEN RAISE EXCEPTION
            'replacement dataset is not eligible for exact immutable registration'; END IF;
          SELECT count(*) INTO bad_chunks
            FROM market_historicalingestionchunk c
            JOIN market_historicaltimestampinventory i ON i.id=c.discovery_inventory_id
            LEFT JOIN LATERAL (
              SELECT r.id AS run_id, r.fetched_count, r.stored_count
                FROM market_historicalingestionattempt a
                JOIN market_ingestionrun r ON r.id=a.ingestion_run_id
                 AND r.status='succeeded'
                WHERE a.chunk_id=c.id LIMIT 1) success ON true
            LEFT JOIN LATERAL (
              SELECT count(*) AS n,
                     market_sha256(coalesce(jsonb_agg(
                       market_discovery_timestamp(cd.timestamp)
                       ORDER BY cd.timestamp),'[]')) AS ts_hash
                FROM market_candle cd WHERE cd.ingestion_run_id=success.run_id) candles
              ON true
            WHERE c.plan_id=reg.plan_id AND c.dataset_version_id=reg.dataset_version_id
              AND (success.run_id IS NULL
                OR success.fetched_count<>i.observation_count
                OR success.stored_count<>i.observation_count
                OR candles.n<>i.observation_count
                OR candles.ts_hash<>i.timestamp_set_sha256);
          IF bad_chunks<>0 THEN RAISE EXCEPTION
            'replacement candles do not equal the sealed inventory'; END IF;
          SELECT count(*) INTO bad_series FROM (
            SELECT ins.code AS icode, granularities.granularity AS gran, ins.id AS iid
            FROM market_instrument ins
            JOIN jsonb_array_elements_text(plan.instruments) plan_instruments(code)
              ON plan_instruments.code=ins.code
            CROSS JOIN jsonb_array_elements_text(plan.granularities)
              granularities(granularity)) series
            WHERE (SELECT coalesce(sum(c.expected_observation_count),0)
                   FROM market_historicalingestionchunk c
                   WHERE c.plan_id=reg.plan_id
                     AND c.dataset_version_id=reg.dataset_version_id
                     AND c.instrument_id=series.iid AND c.granularity=series.gran)
                  <>(SELECT count(*) FROM market_candle cd
                     WHERE cd.dataset_version_id=reg.dataset_version_id
                       AND cd.instrument_id=series.iid AND cd.granularity=series.gran)
               OR (reg.row_counts->>(series.icode||':'||series.gran))::integer
                  <>(SELECT count(*) FROM market_candle cd
                     WHERE cd.dataset_version_id=reg.dataset_version_id
                       AND cd.instrument_id=series.iid AND cd.granularity=series.gran)
               OR (reg.missingness->>(series.icode||':'||series.gran))::integer<>0
               OR (reg.first_last_timestamps->(series.icode||':'||series.gran)->>'first')::timestamptz
                  IS DISTINCT FROM (SELECT min(cd.timestamp) FROM market_candle cd
                     WHERE cd.dataset_version_id=reg.dataset_version_id
                       AND cd.instrument_id=series.iid AND cd.granularity=series.gran)
               OR (reg.first_last_timestamps->(series.icode||':'||series.gran)->>'last')::timestamptz
                  IS DISTINCT FROM (SELECT max(cd.timestamp) FROM market_candle cd
                     WHERE cd.dataset_version_id=reg.dataset_version_id
                       AND cd.instrument_id=series.iid AND cd.granularity=series.gran);
          IF bad_series<>0 THEN RAISE EXCEPTION
            'replacement series do not reconstruct the sealed inventory'; END IF;
        END"""


def _governance():
    return import_module("market.migrations.0014_historical_discovery_supersession")


def _execute(schema_editor, statement):
    # psycopg parses % as a placeholder even with no params; escape literal
    # percent signs so restored verbatim bodies keep single % once stored.
    schema_editor.execute(statement.replace("%", "%%"))


def _require_no_contract_evidence(schema_editor, action):
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(
            """SELECT EXISTS(SELECT 1 FROM market_historicaldatacontract)
                   OR EXISTS(SELECT 1 FROM market_historicaldatasetplan
                             WHERE data_contract_id IS NOT NULL)
                   OR EXISTS(SELECT 1 FROM market_datasetversion
                             WHERE data_contract_sha256 IS NOT NULL)
                   OR EXISTS(SELECT 1 FROM market_datasetregistration
                             WHERE data_contract_id IS NOT NULL)
                   OR EXISTS(SELECT 1 FROM market_historicalingestionchunk
                             WHERE discovery_inventory_id IS NOT NULL)"""
        )
        if cursor.fetchone()[0]:
            raise RuntimeError(f"provider-observed contract evidence prohibits gate1b {action}")


def preflight_data_contract(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        return
    governance = _governance()
    problems = []
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(governance.FUNCTION_FINGERPRINT_SQL, [list(REQUIRED_0018_FUNCTIONS)])
        found_functions = {}
        for name, identity_arguments, fingerprint in cursor.fetchall():
            found_functions.setdefault(name, []).append((identity_arguments, fingerprint))
        for name, expected in sorted(REQUIRED_0018_FUNCTIONS.items()):
            candidates = found_functions.get(name, [])
            if not candidates:
                problems.append(f"required 0018 function {name} is missing")
            elif len(candidates) > 1:
                problems.append(f"required 0018 function {name} has ambiguous overloads")
            elif candidates[0] != tuple(expected):
                problems.append(f"required 0018 function {name} does not match its 0018 definition")
        cursor.execute(governance.TRIGGER_FINGERPRINT_SQL)
        found_triggers = {}
        for table, name, fingerprint in cursor.fetchall():
            found_triggers.setdefault((table, name), []).append(fingerprint)
        for (table, name), expected in sorted(REQUIRED_0018_TRIGGERS.items()):
            candidates = found_triggers.get((table, name), [])
            if not candidates:
                problems.append(f"required 0018 trigger {name} on {table} is missing")
            elif len(candidates) > 1:
                problems.append(f"required 0018 trigger {name} on {table} is ambiguous")
            elif candidates[0] != expected:
                problems.append(
                    f"required 0018 trigger {name} on {table} does not match its 0018 definition"
                )
    if problems:
        raise RuntimeError(
            "migration 0019 preflight rejected the current catalog: " + "; ".join(problems)
        )


def install_data_contract_governance(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        return
    _execute(
        schema_editor,
        "CREATE FUNCTION market_validate_data_contract() RETURNS trigger AS $governed$"
        + DATA_CONTRACT_VALIDATE_PROSRC
        + "$governed$ LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE FUNCTION market_data_contract_reject_mutation() RETURNS trigger AS $governed$"
        + DATA_CONTRACT_MUTATION_PROSRC
        + "$governed$ LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE FUNCTION market_data_contract_reject_truncate() RETURNS trigger AS $governed$"
        + DATA_CONTRACT_TRUNCATE_PROSRC
        + "$governed$ LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE FUNCTION market_validate_replacement_plan("
        "plan market_historicaldatasetplan) RETURNS void AS $governed$"
        + REPLACEMENT_PLAN_PROSRC
        + "$governed$ LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE FUNCTION market_validate_replacement_chunk("
        "chunk market_historicalingestionchunk) RETURNS void AS $governed$"
        + REPLACEMENT_CHUNK_PROSRC
        + "$governed$ LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE FUNCTION market_validate_replacement_dataset("
        "dataset market_datasetversion) RETURNS void AS $governed$"
        + REPLACEMENT_DATASET_PROSRC
        + "$governed$ LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE FUNCTION market_validate_replacement_registration("
        "reg market_datasetregistration) RETURNS void AS $governed$"
        + REPLACEMENT_REGISTRATION_PROSRC
        + "$governed$ LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE TRIGGER market_data_contract_validate BEFORE INSERT "
        "ON market_historicaldatacontract FOR EACH ROW "
        "EXECUTE FUNCTION market_validate_data_contract();",
    )
    _execute(
        schema_editor,
        "CREATE TRIGGER market_data_contract_append_only BEFORE UPDATE OR DELETE "
        "ON market_historicaldatacontract FOR EACH ROW "
        "EXECUTE FUNCTION market_data_contract_reject_mutation();",
    )
    _execute(
        schema_editor,
        "CREATE TRIGGER market_data_contract_reject_truncate BEFORE TRUNCATE "
        "ON market_historicaldatacontract FOR EACH STATEMENT "
        "EXECUTE FUNCTION market_data_contract_reject_truncate();",
    )
    _execute(
        schema_editor,
        "CREATE OR REPLACE FUNCTION market_validate_historical_plan() "
        "RETURNS trigger AS $governed$" + HISTORICAL_PLAN_GATE1B_PROSRC + "$governed$ "
        "LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE OR REPLACE FUNCTION market_validate_historical_chunk() "
        "RETURNS trigger AS $governed$" + HISTORICAL_CHUNK_GATE1B_PROSRC + "$governed$ "
        "LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE OR REPLACE FUNCTION market_validate_historical_dataset() "
        "RETURNS trigger AS $governed$" + HISTORICAL_DATASET_GATE1B_PROSRC + "$governed$ "
        "LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE OR REPLACE FUNCTION market_validate_dataset_registration() "
        "RETURNS trigger AS $governed$"
        + DATASET_REGISTRATION_GATE1B_PROSRC
        + "$governed$ LANGUAGE plpgsql;",
    )


def remove_data_contract_governance(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        return
    _require_no_contract_evidence(schema_editor, "reversal")
    _execute(
        schema_editor,
        "CREATE OR REPLACE FUNCTION market_validate_historical_plan() "
        "RETURNS trigger AS $governed$" + HISTORICAL_PLAN_0018_PROSRC + "$governed$ "
        "LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE OR REPLACE FUNCTION market_validate_historical_chunk() "
        "RETURNS trigger AS $governed$" + HISTORICAL_CHUNK_0018_PROSRC + "$governed$ "
        "LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE OR REPLACE FUNCTION market_validate_historical_dataset() "
        "RETURNS trigger AS $governed$" + HISTORICAL_DATASET_0018_PROSRC + "$governed$ "
        "LANGUAGE plpgsql;",
    )
    _execute(
        schema_editor,
        "CREATE OR REPLACE FUNCTION market_validate_dataset_registration() "
        "RETURNS trigger AS $governed$"
        + DATASET_REGISTRATION_0018_PROSRC
        + "$governed$ LANGUAGE plpgsql;",
    )
    for statement in (
        "DROP TRIGGER market_data_contract_validate ON market_historicaldatacontract;",
        "DROP TRIGGER market_data_contract_append_only ON market_historicaldatacontract;",
        "DROP TRIGGER market_data_contract_reject_truncate ON market_historicaldatacontract;",
        "DROP FUNCTION market_validate_data_contract();",
        "DROP FUNCTION market_data_contract_reject_mutation();",
        "DROP FUNCTION market_data_contract_reject_truncate();",
        "DROP FUNCTION market_validate_replacement_plan(market_historicaldatasetplan);",
        "DROP FUNCTION market_validate_replacement_chunk(market_historicalingestionchunk);",
        "DROP FUNCTION market_validate_replacement_dataset(market_datasetversion);",
        "DROP FUNCTION market_validate_replacement_registration(market_datasetregistration);",
    ):
        _execute(schema_editor, statement)


